chmod 755 /opt/sbin/mtun /opt/etc/init.d/S80mihomo-tun
chmod 600 /opt/lib/mtun-lib.sh
. /opt/lib/mtun-lib.sh
mt_ipv4 "$client_ip" || die 'Invalid client IPv4 address.'
ip -4 route get "$client_ip" | grep -q ' dev br0 ' || die 'Client must be on the main br0 LAN.'
lan_ip=$(ip -4 addr show br0 | awk '/inet / {split($2,a,"/"); print a[1]; exit}')
mt_ipv4 "$lan_ip" || die 'Cannot identify LAN IPv4 on br0.'
[ "$client_ip" != "$lan_ip" ] || die 'Enter the PC address, not the router address.'
ping -c 1 -W 1 "$client_ip" >/dev/null 2>&1 || true
mac=$(ip -4 neigh show "$client_ip" dev br0 | awk '/lladdr/ {for(i=1;i<NF;i++) if($i=="lladdr") {print $(i+1); exit}}')
if [ -z "$mac" ]; then mac=$(awk -v target="$client_ip" '$1==target && $4!="00:00:00:00:00:00" {print $4; exit}' /proc/net/arp); fi
prompt "PC MAC address [$mac]: "
mac=${answer:-$mac}
printf '%s %s\n' "$client_ip" "$mac" > "$tmp/clients"
mt_validate_clients "$tmp/clients" || die 'Invalid client MAC address. Find it in Keenetic device details.'
# Refuse routing-table collisions on first installation. Our own files identify
# a repeat installation, but no unrelated priority-100 rules are deleted.
if [ ! -f "$MT_HOME/config.json" ]; then
 [ -z "$(ip -4 route show table 2023 2>/dev/null)" ] || die 'Routing table 2023 is already in use.'
 if ip -4 rule show | grep -Eq '^100:'; then die 'Routing priority 100 is already in use.'; fi
fi
fetch() { curl --noproxy '*' --proto '=https' --proto-redir '=https' -fLsS --connect-timeout 15 --max-time 240 "$1" -o "$2"; }
phase 'Verified Mihomo core and panel downloads'
fetch https://github.com/MetaCubeX/mihomo/releases/download/v1.19.32/mihomo-linux-arm64-v1.19.32.gz "$tmp/mihomo.gz"
echo "9dd862e28b46ff7d775f169cceebc28deccaa0a9e804237d421cd2571e0caba0  $tmp/mihomo.gz" | sha256sum -c - >/dev/null || die 'Mihomo checksum mismatch.'
gzip -dc "$tmp/mihomo.gz" > /opt/sbin/mihomo-tun-core.new
chmod 755 /opt/sbin/mihomo-tun-core.new
/opt/sbin/mihomo-tun-core.new -v || die 'Mihomo cannot execute on this firmware.'
fetch https://github.com/MetaCubeX/metacubexd/releases/download/v1.273.1/compressed-dist.tgz "$tmp/ui.tgz"
echo "a178e00b67acabcda2dcef00afa90be6a7bb261e466a67dad58c8478d9553603  $tmp/ui.tgz" | sha256sum -c - >/dev/null || die 'Panel checksum mismatch.'
mkdir "$tmp/ui"
tar -xzf "$tmp/ui.tgz" -C "$tmp/ui"
[ -f "$tmp/ui/index.html" ] || die 'Invalid panel archive.'
phase 'Subscription download and isolated provider validation'
url=$(cat "$tmp/source-url")
curl --noproxy '*' --proto '=https' --proto-redir '=https' -fLsS --connect-timeout 15 --max-time 120 --max-filesize 4194304 "$url" > "$tmp/subscription.txt" 2> "$tmp/download.log" || die 'Subscription download failed. Initial installation requires normal internet.'
unset url
backup="$MT_HOME/backup-$(date +%Y%m%d-%H%M%S)-$$"
mkdir "$backup"
for file in config.json clients subscription.txt source-url; do
 [ ! -f "$MT_HOME/$file" ] || cp -a "$MT_HOME/$file" "$backup/$file"
done
if [ -f "$MT_HOME/config.json" ]; then secret=$(jq -r '.secret' "$MT_HOME/config.json")
else secret=$(od -An -N24 -tx1 /dev/urandom | tr -d ' \n'); fi
[ -n "$secret" ] && [ "$secret" != null ] || die 'Invalid panel secret.'
mt_generate "$lan_ip" "$secret" true > "$tmp/config.json"
unset secret
mt_validate_provider "$tmp" /opt/sbin/mihomo-tun-core.new || die 'Subscription contains no usable Mihomo nodes. Existing service was not stopped.'
# Replace the binary only after its checksum, execution and provider checks. On a clean
# setup no running instance exists; on repeat stop the owned service first.
if mt_pid; then sh /opt/etc/init.d/S80mihomo-tun stop; fi
if [ -f /opt/sbin/mihomo-tun-core ]; then cp -a /opt/sbin/mihomo-tun-core "$backup/core"; fi
mv /opt/sbin/mihomo-tun-core.new /opt/sbin/mihomo-tun-core
phase 'Publish configuration and enable TUN'
for file in config.json clients subscription.txt source-url; do
 cp "$tmp/$file" "$MT_HOME/$file.new"; mv "$MT_HOME/$file.new" "$MT_HOME/$file"
done
if [ -d "$MT_HOME/ui" ]; then mv "$MT_HOME/ui" "$backup/ui"; fi
cp -a "$tmp/ui" "$MT_HOME/ui"
cat > /opt/etc/ndm/netfilter.d/100-mihomo-tun.sh <<'NETFILTER'
#!/bin/sh
/opt/etc/init.d/S80mihomo-tun firewall >/dev/null 2>&1 || logger -t mihomo-tun 'Cannot restore TUN firewall; run mtun check'
NETFILTER
chmod 755 /opt/etc/ndm/netfilter.d/100-mihomo-tun.sh
sh /opt/etc/init.d/S80mihomo-tun enable
# Flush only this PC's old conntrack sessions, not the entire home network.
conntrack -D -s "$client_ip" >/dev/null 2>&1 || true
phase 'Select a working server'
mtun best || die 'No server passed HTTPS. TUN stays guarded; use the panel to select another server or mtun stop.'
mtun check
mkdir -p /opt/etc/cron.d
printf '* * * * * root /opt/etc/init.d/S80mihomo-tun guard >/dev/null 2>&1\n' > /opt/etc/cron.d/mihomo-tun
sh /opt/etc/init.d/S10cron start
pidof cron >/dev/null || die 'Entware cron did not start.'
sync
phase 'Ready'
mtun panel
echo "PC: $client_ip ($mac). Reserve this IPv4 address in Keenetic DHCP."
echo 'In MetaCubeXD, add the API address above and its Secret, then select PROXY.'
echo 'Commands: mtun list; mtun use NUMBER; mtun update; mtun change; mtun stop; mtun start.'
echo 'PC proxy/VPN settings stay unchanged. Corporate VPN compatibility must be checked on that PC.'
echo "Backups: $backup"
ok=yes
